// Adapted from organized-experiment-zz7 src/services/purchaseOrderService.ts:124-156 @ de75cd6
// (+ purchaseOrderRepository.ts:93-110 approve(), purchaseOrderSchemas.ts:75-96 transition map).
// Prisma replaced by an injected repository; the guide's two fixes are APPLIED here
// (docs/architecture/auth-and-permissions.md findings 1 and 3): no self-approval, and the
// status guard is part of the conditional write.
export class ForbiddenError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 403;
  }
}
export class ConflictError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 409;
  }
}
export class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 404;
  }
}

const transitions = {
  DRAFT: ["PENDING_APPROVAL", "CANCELLED"],
  PENDING_APPROVAL: ["APPROVED", "CANCELLED"],
  APPROVED: ["PARTIALLY_RECEIVED", "RECEIVED", "CLOSED", "CANCELLED"],
  PARTIALLY_RECEIVED: ["RECEIVED", "CLOSED"],
  RECEIVED: ["CLOSED"],
  CLOSED: [],
  CANCELLED: [],
};

export function assertPurchaseOrderStatusTransition(fromStatus, toStatus) {
  if (!transitions[fromStatus].includes(toStatus)) {
    throw new ConflictError(`Invalid purchase order transition from ${fromStatus} to ${toStatus}`);
  }
  return true;
}

/** In-memory stand-in for the Prisma repository; `yieldBetween` lets a test interleave two requests. */
export function createRepository(rows, { yieldBetween = false } = {}) {
  const audit = [];
  return {
    audit,
    async findById(tenantId, id) {
      const row = rows.find((r) => r.id === id && r.tenantId === tenantId);
      const snapshot = row ? { ...row } : null;
      if (yieldBetween) await new Promise((r) => setTimeout(r, 5));
      return snapshot;
    },
    async approve(where, approvedById) {
      const hits = rows.filter((r) => Object.entries(where).every(([k, v]) => r[k] === v));
      for (const r of hits) {
        r.status = "APPROVED";
        r.approvedById = approvedById;
      }
      return { count: hits.length };
    },
    async auditCreate(entry) {
      audit.push(entry);
    },
  };
}

export async function approvePurchaseOrder(repo, session, purchaseOrderId) {
  const purchaseOrder = await repo.findById(session.tenantId, purchaseOrderId);

  if (!purchaseOrder) {
    throw new NotFoundError("Purchase order was not found.");
  }

  if (purchaseOrder.requestedById === session.userId) {
    throw new ForbiddenError("You cannot approve a purchase order you requested.");
  }

  assertPurchaseOrderStatusTransition(purchaseOrder.status, "APPROVED");

  const result = await repo.approve(
    { id: purchaseOrderId, tenantId: session.tenantId, status: "PENDING_APPROVAL" },
    session.userId,
  );

  if (result.count === 0) {
    throw new ConflictError("Purchase order is no longer pending approval.");
  }

  await repo.auditCreate({
    action: "purchaseOrder.approved",
    actorUserId: session.userId,
    entityId: purchaseOrderId,
    metadata: { fromStatus: purchaseOrder.status, toStatus: "APPROVED" },
  });

  return { id: purchaseOrderId, status: "APPROVED", approvedById: session.userId };
}

